package com.logatron.processor;
import com.logatron.processor.protect.SensitiveDataMasker;import com.logatron.processor.dlq.DeadLetterFactory;import com.logatron.processor.parse.ProcessingException;import com.logatron.processor.validate.EnvelopeValidator;import com.logatron.processor.deduplicate.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.assertj.core.api.Assertions.*;
class ProtectionAndReliabilityTest {@Test void masksAdversarialSecretForms(){var m=new SensitiveDataMasker(TestFixtures.properties());String input="Authorization: Bearer eyJabc12345.abcdefghijk.signature123 password=myPassword123 apiKey=SECRET123 ?access_token=urlsecret jdbc:postgresql://user:dbpass@host/db";String safe=m.mask(input);assertThat(safe).doesNotContain("myPassword123","SECRET123","urlsecret","dbpass","eyJabc12345").contains("[REDACTED]");}
 @Test void redactedDlqIsBoundedAndHasHash(){var f=new DeadLetterFactory(new SensitiveDataMasker(TestFixtures.properties()));var d=f.create("password=supersecret "+"x".repeat(3000),TestFixtures.raw(com.logatron.contracts.ingestion.ParserProfile.JSON,"bad"),"PARSE",new ProcessingException("MALFORMED_JSON","bad"),2);assertThat(d.redactedPayloadPreview()).doesNotContain("supersecret").hasSizeLessThanOrEqualTo(2048);assertThat(d.payloadHash()).hasSize(64);assertThat(d.retryCount()).isEqualTo(2);}
 @Test void rejectsFutureSchemaVersion(){var raw=TestFixtures.raw(com.logatron.contracts.ingestion.ParserProfile.JSON,"{}");var future=new com.logatron.contracts.ingestion.RawLogEnvelope(2,raw.eventId(),raw.observedTimestamp(),raw.collector(),raw.resource(),raw.source(),raw.payload(),raw.attributes());assertThatThrownBy(()->new EnvelopeValidator(TestFixtures.properties()).validate(future)).isInstanceOf(ProcessingException.class);}
 @Test void fingerprintIsStableAndIgnoresIngestionIdentity(){var f=new Fingerprinter();assertThat(f.fingerprint(TestFixtures.canonical("same"))).isEqualTo(f.fingerprint(TestFixtures.canonical("same"))).hasSize(64);assertThat(f.fingerprint(TestFixtures.canonical("same"))).isNotEqualTo(f.fingerprint(TestFixtures.canonical("different")));}
 @Test void duplicateTrackerIsOnlyBoundedOptimization(){var t=new DuplicateTracker(TestFixtures.properties());UUID id=UUID.randomUUID();assertThat(t.seen(id)).isFalse();assertThat(t.seen(id)).isTrue();}}